import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Position / Rotation / Scale from scene placement ---
  const pos = config.scenePlacement?.position ?? [0, 0, 0];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];

  // --- Load GLB mesh ---
  const meshUrl = config.meshUrl;
  if (!meshUrl) {
    const fallback = new THREE.Group();
    fallback.userData.cleanup = () => {};
    return fallback;
  }
  const loaded = ctx.glbLoader.get(meshUrl);
  const mesh = loaded.scene.clone(true);
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- Interaction handlers ---
  const handlers = {};
  let hoverTween = null;
  let pressTween = null;

  handlers.mouseenter = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: pos[1] + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.mouseleave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: pos[1],
      duration: 0.5,
      ease: 'power2.out'
    });
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: scl[0],
      y: scl[1],
      z: scl[2],
      duration: 0.2,
      ease: 'power2.out'
    });
  };

  handlers.mousedown = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: scl[0] * 0.97,
      y: scl[1] * 0.97,
      z: scl[2] * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };

  handlers.mouseup = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: scl[0],
      y: scl[1],
      z: scl[2],
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };

  handlers.click = () => {
    // Emit a select event (the framework calls this handler)
    const tl = gsap.timeline();
    tl.to(mesh.scale, {
      x: scl[0] * 0.97,
      y: scl[1] * 0.97,
      z: scl[2] * 0.97,
      duration: 0.06,
      ease: 'back.out(1.7)'
    }).to(mesh.scale, {
      x: scl[0],
      y: scl[1],
      z: scl[2],
      duration: 0.06,
      ease: 'back.out(1.7)'
    });
  };

  mesh.userData.handlers = handlers;

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
  };

  return mesh;
}
